        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, in_channels, height_out, width_out).
        """
        return self.depthwise_conv(x)

class custom_cuda_op(in_channels, kernel_size, stride, padding, bias):
    """
    Custom CUDA operator for depthwise 2D convolution.

    This implementation uses a custom kernel to perform the depthwise convolution
    operation. The kernel is designed to handle the depthwise nature of the operation,
    where each channel is processed independently.

    Args:
        in_channels (int): Number of channels in the input tensor.
        kernel_size (int): Size of the convolution kernel.
        stride (int, optional): Stride of the convolution. Defaults to 1.
        padding (int, optional): Padding applied to the input. Defaults to 0.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.

    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, bias: bool = False):
        # Define the custom CUDA kernel for depthwise convolution
        self.kernel = """
            // Custom CUDA kernel for depthwise 2D convolution
            __global__ void depthwise_conv_kernel(
                in_channels,
                kernel_size,
                stride,
                padding,
                bias,
                x, y, z, w
            ) {
                int idx = blockIdx.x * blockDim.x + threadIdx.x;
                if (idx < kernel_size * kernel_size) {
                    // Calculate the position within the kernel
                    int i = idx / (kernel_size * kernel_size);
                    int j = idx % (kernel_size * kernel_size);

                    // Apply depthwise convolution
                    for c in range(in_channels):
                        // Compute the filtered value for each channel
                        float val = 0.0;
                        for k in range(kernel_size):
                            // Calculate the offset from the input position
                            int offset_x = (k * kernel_size + j) % stride;
                            int offset_y = (k * kernel_size + i) % stride;
                            // Apply depthwise convolution with bias
                            val += x[..., c, offset_x, offset_y] * kernel[c]
                        if bias:
                            val += bias * x[..., c, offset_x, offset_y]

                        // Store the result in the output tensor
                        out[idx] = val
                    }
                }
            }

        # Compile the custom CUDA kernel for depthwise convolution
        return load_inline(
            name="depthwise_conv_cuda",
            cpp_sources=custom_cuda_op.cpp_source,
            cuda_sources=custom_cuda_op.cpp_source,
